#!/usr/bin/env dotnet
// Explore Friday the 13th in the proleptic Gregorian calendar

// Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
DateTime? earliest = null;

for (int year = 1; year <= 400 && earliest is null; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = d;
            break;
        }
    }
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd}");
Console.WriteLine();

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
var byMonth = new int[12];
var byDayOfWeek = new int[7]; // how many 13ths fall on each day of week

for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        byDayOfWeek[(int)d.DayOfWeek]++;
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            count++;
            byMonth[month - 1]++;
        }
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine();
Console.WriteLine("Distribution of the 13th by day of week:");
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-10}: {byDayOfWeek[(int)dow]}");

Console.WriteLine();
Console.WriteLine("Friday the 13ths by month:");
var monthNames = System.Globalization.CultureInfo.InvariantCulture.DateTimeFormat.MonthNames;
for (int i = 0; i < 12; i++)
    Console.WriteLine($"  {monthNames[i],-10}: {byMonth[i]}");

